  select * into item from public.catalog_items where kind='board' and code=entry->>'code';
  if found then
   if item.category_code is distinct from entry->>'category_code' or item.retired_at is not null or item.name is distinct from entry->>'name' or not exists(select 1 from public.board_skus b where b.item_id=item.id and b.thickness_mm=(entry->>'thickness_mm')::numeric and b.sheet_width_mm=(entry->>'sheet_width_mm')::numeric and b.sheet_height_mm=(entry->>'sheet_height_mm')::numeric) then raise exception 'Existing board conflicts: %',entry->>'code'; end if;
  else
   ident:=public.cutplan_catalog_change(jsonb_build_object('action','create','kind','board','category_code',entry->>'category_code','code',entry->>'code','name',entry->>'name','details',entry));
   update public.catalog_items set source_name=entry->>'source_name',source_url=entry->>'source_url',source_captured_at=now() where id=ident;
   if entry->>'price' is not null then
    perform public.cutplan_catalog_change(jsonb_build_object('action','price','id',ident,'version',1,'amount',entry->>'price','unit','sheet','reason','Published supplier price captured 2026-10-25; draft pending dealer confirmation.'));prices:=prices+1;
   end if;
   created:=created+1;
  end if;
 end loop;
 raise notice 'Created % variants and % draft prices',created,prices;
